      "stepByStep": "1. Clemmensen reduction selectively reduces carbonyl groups of aldehydes and ketones into methylene ($-CH_2-$) groups using zinc amalgam in concentrated $HCl$.\n2. It operates under strongly acidic conditions and is suitable for compounds containing acid-stable groups.\n3. In contrast, Wolff-Kishner reduction achieves the same conversion using hydrazine ($NH_2NH_2$) and potassium hydroxide in ethylene glycol under strongly basic conditions.\n4. Rosenmund reduction converts acyl chlorides to aldehydes ($Pd/BaSO_4$), while Stephen reduction converts nitriles to aldehydes ($SnCl_2/HCl$).",
