    "explanation": "1. CONCEPT & PRINCIPLE:\nStructural prerequisites for haloform (iodoform) reaction.\n\n2. GIVEN INFORMATION / DATA:\nCompounds tested with $I_2 + NaOH$ (sodium hypoiodite reagent).\n\n3. FORMULA / EQUATION:\nPositive test requires either a methyl carbonyl group ($CH_3-C=O$) or a methyl carbinol group ($CH_3-CH(OH)-$).\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. The iodoform test specifically identifies compounds containing a terminal methyl ketone group ($\\text{CH}_3-\\text{C}=\\text{O}$) or an alcohol oxidizable to it ($\\text{CH}_3-\\text{CH}(\\text{OH})-$).\n2. In pentan-2-one ($CH_3-CO-CH_2CH_2CH_3$), three alpha-hydrogens on the methyl group undergo rapid successive iodination to form $-CI_3$.\n3. Subsequent nucleophilic attack by $OH^-$ cleaves the $C-C$ bond, precipitating yellow crystalline iodoform ($CHI_3$, MP $119^\\circ\\text{C}$) with a characteristic antiseptic odor.\n4. Pentan-3-one has no methyl ketone group (only $-CH_2-CO-CH_2-$); benzaldehyde has no alpha-hydrogens; methanol cannot be oxidized to a methyl ketone.\n\n5. FINAL CONCLUSION:\nPentan-2-one ($\\text{CH}_3\\text{COCH}_2\\text{CH}_2\\text{CH}_3$)\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nPentan-3-one is a symmetrical ketone without a methyl ketone group; benzaldehyde lacks alpha-hydrogens.",
