    "question": "Q234. (NEET Medium) The reduction of a carbonyl group ($>\\text{C}=\\text{O}$) of aldehydes or ketones to a methylene group ($-\\text{CH}_2-$) using amalgamated zinc and concentrated hydrochloric acid ($Zn-Hg / \\text{conc. HCl}$) is known as:",
