    "question": "Q240. (NEET Medium) In the Hell-Volhard-Zelinsky (HVZ) reaction, carboxylic acids having an $\\alpha$-hydrogen react with chlorine or bromine in the presence of red phosphorus to yield:",
    "options": {
      "A": "Acid chlorides",
      "B": "$\beta$-Halocarboxylic acids",
      "C": "Alkanes",
      "D": "$\\alpha$-Halocarboxylic acids"
    },
